import numpy as np
# construct exact grid pattern from observed 4x4 complete tiles
G=np.zeros((30,30),dtype=int)
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts=[1,8,15,22]
for tr,r in enumerate(starts):
 for tc,c in enumerate(starts):
  G[r:r+5,c:c+5]=4
  G[r+1:r+4,c+1:c+4]=colors[tr][tc]
# partial fifth column at c29 for rows 1..5 and row29 tile across columns as input
for r in starts[:4]: G[r:r+5,29]=4
G[29,:]=0
# observed final row all zeros except col29=0 (data row starts 0s) actually row29: col29=0
# add connections, per same color tile centers horizontally/vertically
for tr,r in enumerate(starts):
 for color in (2,3,8):
  inds=[tc for tc,x in enumerate(colors[tr]) if x==color]
  for a,b in zip(inds,inds[1:]):
   for tc in range(a,b):
    G[r+1:r+4,starts[tc]+5:starts[tc+1]]=color
for tc,c in enumerate(starts):
 for color in (2,3,8):
  inds=[tr for tr in range(4) if colors[tr][tc]==color]
  for a,b in zip(inds,inds[1:]):
   for tr in range(a,b):
    G[starts[tr]+5:starts[tr+1],c+1:c+4]=color
print('\n'.join(' '.join(map(str,row)) for row in G))

